290→// TestFindMostRecentSession_FiltersByWorktree tests that FindMostRecentSession
291→// returns sessions from the current worktree, not from other worktrees.
292→func TestFindMostRecentSession_FiltersByWorktree(t *testing.T) {
293→	dir := t.TempDir()
294→	_, err := git.PlainInit(dir, false)
295→	if err != nil {
296→		t.Fatalf("failed to init git repo: %v", err)
297→	}
298→
299→	t.Chdir(dir)
300→
301→	// Get the resolved worktree path (git resolves symlinks, e.g. /var → /private/var on macOS)
302→	resolvedDir, err := GetWorktreePath()
303→	if err != nil {
304→		t.Fatalf("GetWorktreePath() error = %v", err)
305→	}
306→
307→	older := time.Now().Add(-1 * time.Hour)
308→	newer := time.Now()
309→
310→	// Session from a different worktree (more recent)
311→	otherWorktree := &SessionState{
312→		SessionID:           "other-worktree-session",
313→		BaseCommit:          "abc1234",
314→		WorktreePath:        "/some/other/worktree",
315→		StartedAt:           newer,
316→		LastInteractionTime: &newer,
317→		Phase:               "idle",
318→	}
319→
320→	// Session from current worktree (older)
321→	currentWorktree := &SessionState{
322→		SessionID:           "current-worktree-session",
323→		BaseCommit:          "xyz7890",
324→		WorktreePath:        resolvedDir, // matches current worktree
325→		StartedAt:           older,
326→		LastInteractionTime: &older,
327→		Phase:               "idle",
328→	}
329→
330→	if err := SaveSessionState(otherWorktree); err != nil {
331→		t.Fatalf("SaveSessionState() error = %v", err)
332→	}
333→	if err := SaveSessionState(currentWorktree); err != nil {
334→		t.Fatalf("SaveSessionState() error = %v", err)
335→	}
336→
337→	// FindMostRecentSession should return the current worktree's session,
338→	// not the other worktree's session (even though it's more recent).
339→	result := FindMostRecentSession()
340→	if result != "current-worktree-session" {
341→		t.Errorf("FindMostRecentSession() = %q, want %q (should prefer current worktree)",
342→			result, "current-worktree-session")
343→	}
344→}
